pub mod auth;
pub mod board;
pub mod frame;
pub mod object;
pub mod store;
pub mod view;

use std::cell::{Cell, RefCell};
use std::rc::Rc;
use std::time::Duration;

use worker::*;

use auth::{Access, AccessApp, Keys};
use board::{BoardSync, Session};
use frame::{Frame, FrameKind};
use store::SqlTileStore;

const BOARD_BINDING: &str = "BOARD";
const FLUSH_DELAY: Duration = Duration::from_secs(5);
const IDLE_MS: u64 = 60_000;

const USER_HEADER: &str = "X-Stallion-User";

thread_local! {
    static ACCESS_KEYS: RefCell<Option<(u64, Rc<Keys>)>> = const { RefCell::new(None) };
    static LOGGED_DISABLED: Cell<bool> = const { Cell::new(false) };
}

enum Caller {
    Anonymous,
    User(String),
    Denied(String),
}

async fn access_keys(app: &AccessApp) -> Result<Rc<Keys>> {
    let now = Date::now().as_millis();
    let cached = ACCESS_KEYS.with_borrow(|cache| {
        cache
            .as_ref()
            .filter(|(fetched, _)| now.saturating_sub(*fetched) < auth::KEYS_TTL_MS)
            .map(|(_, keys)| keys.clone())
    });
    if let Some(keys) = cached {
        return Ok(keys);
    }
    let mut response = Fetch::Url(Url::parse(&app.certs_url())?).send().await?;
    if response.status_code() != 200 {
        return Err(Error::RustError(format!(
            "{} returned {}",
            app.certs_url(),
            response.status_code()
        )));
    }
    let keys = Rc::new(auth::parse_keys(&response.text().await?).map_err(Error::RustError)?);
    ACCESS_KEYS.set(Some((now, keys.clone())));
    Ok(keys)
}

async fn caller(req: &Request, env: &Env) -> Result<Caller> {
    let access = Access::from_vars(
        &env.var("ACCESS_TEAM_DOMAIN")?.to_string(),
        &env.var("ACCESS_AUD")?.to_string(),
    )
    .map_err(Error::RustError)?;
    let Access::Enabled(app) = access else {
        if !LOGGED_DISABLED.replace(true) {
            console_log!(
                "Cloudflare Access is disabled: ACCESS_TEAM_DOMAIN and ACCESS_AUD are empty"
            );
        }
        return Ok(Caller::Anonymous);
    };
    let assertion = req.headers().get(auth::ASSERTION_HEADER)?;
    let cookie = req.headers().get("Cookie")?;
    let Some(token) = auth::token(assertion.as_deref(), cookie.as_deref()) else {
        return Ok(Caller::Denied("no Access token".into()));
    };
    let keys = access_keys(&app).await?;
    Ok(
        match auth::verify(token, &keys, &app, Date::now().as_millis() / 1000) {
            Ok(identity) => Caller::User(identity.email),
            Err(reason) => Caller::Denied(reason),
        },
    )
}

fn board_id(path: &str) -> Option<&str> {
    let id = path.strip_prefix("/api/boards/")?.strip_suffix("/ws")?;
    let valid = !id.is_empty()
        && id.len() <= 64
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
    valid.then_some(id)
}

#[event(fetch)]
async fn fetch(req: Request, env: Env, _ctx: Context) -> Result<Response> {
    let user = match caller(&req, &env).await? {
        Caller::Denied(reason) => {
            console_log!("Access rejected the request: {reason}");
            return Response::error("unauthorized", 401);
        }
        Caller::Anonymous => String::new(),
        Caller::User(email) => email,
    };
    let url = req.url()?;
    let Some(id) = board_id(url.path()) else {
        return Response::error("expected /api/boards/{boardId}/ws", 404);
    };
    let forward = req.clone_mut()?;
    let headers = forward.headers();
    headers.delete(USER_HEADER)?;
    if !user.is_empty() {
        headers.set(USER_HEADER, &user)?;
    }
    env.durable_object(BOARD_BINDING)?
        .get_by_name(id)?
        .fetch_with_request(forward)
        .await
}

#[durable_object]
pub struct Board {
    state: State,
    board: RefCell<BoardSync<SqlTileStore>>,
    flush_armed: Cell<bool>,
}

impl Board {
    fn session(ws: &WebSocket) -> Result<Session> {
        Ok(ws.deserialize_attachment()?.unwrap_or_default())
    }

    fn deliver(&self, sender: &WebSocket, outgoing: Vec<board::Outgoing>) -> Result<()> {
        if outgoing.is_empty() {
            return Ok(());
        }
        let sockets = self.state.get_websockets();
        for out in outgoing {
            let bytes = out.frame.encode();
            for ws in &sockets {
                if out.route.reaches(ws == sender, &Self::session(ws)?) {
                    ws.send_with_bytes(&bytes)?;
                }
            }
        }
        Ok(())
    }

    fn reject(ws: &WebSocket, tile_key: String, reason: String) -> Result<()> {
        let frame = Frame::new(tile_key, FrameKind::Reject, reason.into_bytes());
        ws.send_with_bytes(frame.encode())
    }

    fn leave(&self, ws: &WebSocket) -> Result<()> {
        let session = Self::session(ws)?;
        let outgoing = self
            .board
            .borrow_mut()
            .close(&session)
            .map_err(Error::RustError)?;
        self.deliver(ws, outgoing)
    }

    async fn arm_flush(&self) -> Result<()> {
        if self.flush_armed.get() || !self.board.borrow().has_dirty() {
            return Ok(());
        }
        self.flush_armed.set(true);
        let armed = self.state.storage().set_alarm(FLUSH_DELAY).await;
        if armed.is_err() {
            self.flush_armed.set(false);
        }
        armed
    }
}

impl DurableObject for Board {
    fn new(state: State, _env: Env) -> Self {
        let store = SqlTileStore::new(state.storage().sql());
        Board {
            state,
            board: RefCell::new(BoardSync::new(|| Date::now().as_millis(), store)),
            flush_armed: Cell::new(false),
        }
    }

    async fn fetch(&self, req: Request) -> Result<Response> {
        if req.headers().get("Upgrade")?.as_deref() != Some("websocket") {
            return Response::error("expected a websocket upgrade", 426);
        }
        let pair = WebSocketPair::new()?;
        self.state.accept_web_socket(&pair.server);
        let session = Session {
            user: req.headers().get(USER_HEADER)?.unwrap_or_default(),
            ..Session::default()
        };
        pair.server.serialize_attachment(session)?;
        let opening = self.board.borrow().open().map_err(Error::RustError)?;
        for frame in opening {
            pair.server.send_with_bytes(frame.encode())?;
        }
        Response::from_websocket(pair.client)
    }

    async fn websocket_message(
        &self,
        ws: WebSocket,
        message: WebSocketIncomingMessage,
    ) -> Result<()> {
        let WebSocketIncomingMessage::Binary(bytes) = message else {
            return ws.close(Some(1003), Some("frames are binary CBOR"));
        };
        let frame = match Frame::decode(&bytes) {
            Ok(frame) => frame,
            Err(reason) => return ws.close(Some(1007), Some(reason)),
        };
        let tile_key = frame.tile_key.clone();
        let mut session = Self::session(&ws)?;
        let result = self.board.borrow_mut().receive(&mut session, frame);
        match result {
            Ok(outgoing) => {
                ws.serialize_attachment(&session)?;
                self.deliver(&ws, outgoing)?;
                self.arm_flush().await
            }
            Err(reason) => Self::reject(&ws, tile_key, reason),
        }
    }

    async fn websocket_close(
        &self,
        ws: WebSocket,
        _code: usize,
        _reason: String,
        _was_clean: bool,
    ) -> Result<()> {
        self.leave(&ws)
    }

    async fn websocket_error(&self, ws: WebSocket, _error: Error) -> Result<()> {
        self.leave(&ws)
    }

    async fn alarm(&self) -> Result<Response> {
        self.flush_armed.set(false);
        let mut board = self.board.borrow_mut();
        let flushed = board.flush().map_err(Error::RustError)?;
        board.evict_idle(IDLE_MS);
        Response::ok(format!("flushed {flushed} tiles"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn routes_only_board_websocket_paths() {
        assert_eq!(board_id("/api/boards/b-1/ws"), Some("b-1"));
        assert_eq!(board_id("/api/boards//ws"), None);
        assert_eq!(board_id("/api/boards/a/b/ws"), None);
        assert_eq!(board_id("/"), None);
    }
}
use std::collections::HashMap;

use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use rsa::pkcs1v15::{Signature, VerifyingKey};
use rsa::signature::Verifier;
use rsa::{BigUint, RsaPublicKey};
use serde::Deserialize;
use sha2::Sha256;

pub const ASSERTION_HEADER: &str = "Cf-Access-Jwt-Assertion";
pub const COOKIE_NAME: &str = "CF_Authorization";
pub const KEYS_TTL_MS: u64 = 60 * 60 * 1000;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AccessApp {
    pub team_domain: String,
    pub aud: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Access {
    Disabled,
    Enabled(AccessApp),
}

impl Access {
    pub fn from_vars(team_domain: &str, aud: &str) -> Result<Self, String> {
        let team_domain = team_domain
            .trim()
            .trim_start_matches("https://")
            .trim_end_matches('/');
        let aud = aud.trim();
        match (team_domain.is_empty(), aud.is_empty()) {
            (true, true) => Ok(Access::Disabled),
            (false, false) => Ok(Access::Enabled(AccessApp {
                team_domain: team_domain.to_string(),
                aud: aud.to_string(),
            })),
            _ => Err("set both ACCESS_TEAM_DOMAIN and ACCESS_AUD, or neither".into()),
        }
    }
}

impl AccessApp {
    pub fn certs_url(&self) -> String {
        format!("https://{}/cdn-cgi/access/certs", self.team_domain)
    }

    pub fn issuer(&self) -> String {
        format!("https://{}", self.team_domain)
    }
}

pub fn token<'a>(assertion: Option<&'a str>, cookie: Option<&'a str>) -> Option<&'a str> {
    if let Some(value) = assertion.map(str::trim).filter(|v| !v.is_empty()) {
        return Some(value);
    }
    cookie?
        .split(';')
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(name, _)| *name == COOKIE_NAME)
        .map(|(_, value)| value)
        .filter(|v| !v.is_empty())
}

pub type Keys = HashMap<String, RsaPublicKey>;

#[derive(Deserialize)]
struct Jwks {
    keys: Vec<Jwk>,
}

#[derive(Deserialize)]
struct Jwk {
    kid: String,
    kty: String,
    n: String,
    e: String,
}

pub fn parse_keys(jwks: &str) -> Result<Keys, String> {
    let jwks: Jwks = serde_json::from_str(jwks).map_err(|e| format!("invalid JWKS: {e}"))?;
    jwks.keys
        .into_iter()
        .filter(|k| k.kty == "RSA")
        .map(|k| {
            let n = BigUint::from_bytes_be(&b64(&k.n)?);
            let e = BigUint::from_bytes_be(&b64(&k.e)?);
            let key = RsaPublicKey::new(n, e).map_err(|e| format!("invalid RSA key: {e}"))?;
            Ok((k.kid, key))
        })
        .collect()
}

fn b64(part: &str) -> Result<Vec<u8>, String> {
    URL_SAFE_NO_PAD
        .decode(part)
        .map_err(|e| format!("invalid base64url: {e}"))
}

#[derive(Deserialize)]
struct Header {
    alg: String,
    kid: String,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum Audience {
    One(String),
    Many(Vec<String>),
}

impl Audience {
    fn contains(&self, aud: &str) -> bool {
        match self {
            Audience::One(a) => a == aud,
            Audience::Many(all) => all.iter().any(|a| a == aud),
        }
    }
}

#[derive(Deserialize)]
struct Claims {
    aud: Audience,
    iss: String,
    exp: u64,
    #[serde(default)]
    nbf: Option<u64>,
    #[serde(default)]
    email: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Identity {
    pub email: String,
}

pub fn verify(
    token: &str,
    keys: &Keys,
    app: &AccessApp,
    now_secs: u64,
) -> Result<Identity, String> {
    let mut parts = token.split('.');
    let (Some(header), Some(payload), Some(signature), None) =
        (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return Err("malformed JWT".into());
    };
    let head: Header =
        serde_json::from_slice(&b64(header)?).map_err(|e| format!("invalid JWT header: {e}"))?;
    if head.alg != "RS256" {
        return Err(format!("unsupported alg {:?}", head.alg));
    }
    let key = keys
        .get(&head.kid)
        .ok_or_else(|| format!("unknown kid {:?}", head.kid))?;
    let signature = Signature::try_from(b64(signature)?.as_slice())
        .map_err(|e| format!("invalid signature: {e}"))?;
    let signed = &token[..header.len() + 1 + payload.len()];
    VerifyingKey::<Sha256>::new(key.clone())
        .verify(signed.as_bytes(), &signature)
        .map_err(|_| "bad signature".to_string())?;
    let claims: Claims =
        serde_json::from_slice(&b64(payload)?).map_err(|e| format!("invalid JWT claims: {e}"))?;
    if !claims.aud.contains(&app.aud) {
        return Err("wrong audience".into());
    }
    if claims.iss != app.issuer() {
        return Err("wrong issuer".into());
    }
    if claims.exp <= now_secs {
        return Err("expired".into());
    }
    if claims.nbf.is_some_and(|nbf| nbf > now_secs) {
        return Err("not yet valid".into());
    }
    Ok(Identity {
        email: claims.email,
    })
}

#[cfg(test)]
mod tests {
    use std::sync::OnceLock;

    use rsa::RsaPrivateKey;
    use rsa::pkcs1v15::SigningKey;
    use rsa::signature::{SignatureEncoding, Signer};
    use rsa::traits::PublicKeyParts;
    use serde_json::json;

    use super::*;

    const NOW: u64 = 1_800_000_000;

    fn app() -> AccessApp {
        AccessApp {
            team_domain: "team.cloudflareaccess.com".into(),
            aud: "app-aud".into(),
        }
    }

    fn private_key() -> &'static RsaPrivateKey {
        static KEY: OnceLock<RsaPrivateKey> = OnceLock::new();
        KEY.get_or_init(|| RsaPrivateKey::new(&mut rand::thread_rng(), 1024).unwrap())
    }

    fn keys() -> Keys {
        let public = private_key().to_public_key();
        let jwks = json!({ "keys": [{
            "kid": "k1",
            "kty": "RSA",
            "alg": "RS256",
            "n": URL_SAFE_NO_PAD.encode(public.n().to_bytes_be()),
            "e": URL_SAFE_NO_PAD.encode(public.e().to_bytes_be()),
        }]});
        parse_keys(&jwks.to_string()).unwrap()
    }

    fn sign(claims: serde_json::Value) -> String {
        let header = URL_SAFE_NO_PAD.encode(json!({ "alg": "RS256", "kid": "k1" }).to_string());
        let payload = URL_SAFE_NO_PAD.encode(claims.to_string());
        let signed = format!("{header}.{payload}");
        let signature = SigningKey::<Sha256>::new(private_key().clone()).sign(signed.as_bytes());
        format!("{signed}.{}", URL_SAFE_NO_PAD.encode(signature.to_bytes()))
    }

    fn claims(aud: &str, exp: u64) -> serde_json::Value {
        json!({
            "aud": [aud],
            "iss": "https://team.cloudflareaccess.com",
            "exp": exp,
            "email": "[REDACTED-EMAIL]",
        })
    }

    #[test]
    fn accepts_a_valid_token() {
        let identity = verify(&sign(claims("app-aud", NOW + 60)), &keys(), &app(), NOW).unwrap();
        assert_eq!(identity.email, "[REDACTED-EMAIL]");
    }

    #[test]
    fn rejects_a_wrong_audience() {
        let token = sign(claims("other-aud", NOW + 60));
        assert_eq!(
            verify(&token, &keys(), &app(), NOW),
            Err("wrong audience".into())
        );
    }

    #[test]
    fn rejects_an_expired_token() {
        let token = sign(claims("app-aud", NOW - 1));
        assert_eq!(verify(&token, &keys(), &app(), NOW), Err("expired".into()));
    }

    #[test]
    fn rejects_a_bad_signature() {
        let token = sign(claims("app-aud", NOW + 60));
        let forged = URL_SAFE_NO_PAD.encode(claims("app-aud", NOW + 6000).to_string());
        let mut parts: Vec<&str> = token.split('.').collect();
        parts[1] = &forged;
        assert_eq!(
            verify(&parts.join("."), &keys(), &app(), NOW),
            Err("bad signature".into())
        );
    }

    #[test]
    fn disables_only_when_both_vars_are_empty() {
        assert_eq!(Access::from_vars("", ""), Ok(Access::Disabled));
        assert!(Access::from_vars("team.cloudflareaccess.com", "").is_err());
        assert_eq!(
            Access::from_vars("https://team.cloudflareaccess.com/", "app-aud"),
            Ok(Access::Enabled(app()))
        );
    }

    #[test]
    fn reads_the_header_before_the_cookie() {
        assert_eq!(token(Some("h"), Some("CF_Authorization=c")), Some("h"));
        assert_eq!(token(None, Some("a=1; CF_Authorization=c")), Some("c"));
        assert_eq!(token(None, Some("a=1")), None);
    }
}

