impl Board {
    fn session(ws: &WebSocket) -> Result<Session> {
        Ok(ws.deserialize_attachment()?.unwrap_or_default())
    }

    fn deliver(&self, sender: &WebSocket, outgoing: Vec<board::Outgoing>) -> Result<()> {
        if outgoing.is_empty() {
            return Ok(());
