            <path
              d="M9 14L4 9l5-5M4 9h10a6 6 0 010 12h-3"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </button>
        <button
          type="button"
          class="tool"
          aria-label="Redo"
          title="Redo your last undone change (Ctrl+Shift+Z)"
