export function UpdateNotice() {
  const {
    needRefresh: [needRefresh],
    updateServiceWorker,
  } = useRegisterSW();
  if (!needRefresh) return null;
  return (
    <div class="notice" role="status">
      <p>Update available.</p>
      <button type="button" onClick={() => updateServiceWorker(true)}>
        Reload
      </button>
    </div>
  );
}
import { Redirect, Route, Switch } from "wouter-preact";
import { Board } from "./board";

export const DEFAULT_BOARD = "default";

export const decodeBoardId = (segment: string): string => {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
};

export function App() {
  return (
    <Switch>
      <Route path="/b/:boardId">
        {(params) => {
          const boardId = decodeBoardId(params.boardId);
          return <Board key={boardId} boardId={boardId} />;
        }}
      </Route>
      <Route>
        <Redirect to={`/b/${DEFAULT_BOARD}`} replace />
      </Route>
    </Switch>
  );
}
import { boot, showBootFailure } from "./boot";

const root = document.getElementById("app");
if (!root) throw new Error("Missing #app root element in index.html");
boot(
  root,
  () => import("./mount"),
  (message) => showBootFailure(root, message),
);
import { render } from "preact";
import { App } from "./app";
import { UpdateNotice } from "./update-notice";
import "./styles.css";

export const mount = (root: HTMLElement): void =>
  render(
    <>
      <App />
      <UpdateNotice />
    </>,
    root,
  );

