:root {
  --paper: #fbfaf7;
  --panel: #ffffffee;
  --ink: #1f2328;
  --line: #d9d6cf;
  --accent: #0090ff;
  color-scheme: only light;
}

html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.board {
  position: fixed;
  inset: 0;
}

.surface {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.surface.panning {
  cursor: grab;
}

.surface.selecting {
  cursor: default;
}

.surface.erasing {
  cursor: cell;
}

.toolbar {
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 2px 8px #0000001a;
}

.group {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: flex;
  gap: 4px;
}

.tool {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
}

.tool:focus {
  outline: none;
}

.tool:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.tool[aria-pressed="true"] {
  border-color: var(--accent);
}

.tool:disabled {
  opacity: 0.35;
  cursor: default;
}

.dot {
  display: block;
  border-radius: 50%;
  background: var(--ink);
}

.swatch {
  position: relative;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px var(--panel);
}

.swatch[aria-pressed="true"] {
  border-color: transparent;
  box-shadow:
    inset 0 0 0 2px var(--panel),
    0 0 0 2px var(--panel),
    0 0 0 5px var(--ink);
}

.swatch.secondary::after {
  content: "";
  position: absolute;
  right: -5px;
  bottom: -5px;
  width: 10px;
  height: 10px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--ink);
}

.pair {
  position: relative;
}

.chip {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 2px solid var(--panel);
  border-radius: 4px;
}

.chip.back {
  right: 4px;
  bottom: 4px;
}

.chip.front {
  left: 4px;
  top: 4px;
}

  background: #ffffff;
  color: #1c2024;
}

.notice p {
  margin: 0;
}

.status {
  width: 10px;
  height: 10px;
  margin: 0 4px;
  border-radius: 50%;
  background: #8b8d98;
}

.status[data-connection="Connected"] {
  background: #30a46c;
}

.status[data-connection="Reconnecting"] {
  background: #f76b15;
}

.status[data-connection="Offline"] {
  background: #e5484d;
}

.level {
  position: relative;
}

.level-chip {
  min-width: 44px;
  height: 44px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: transparent;
  color: var(--ink);
  font:
    600 15px / 1 system-ui,
    sans-serif;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.level-chip[aria-expanded="true"] {
  border-color: var(--accent);
}

.level-list {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  display: flex;
  flex-direction: column;
  width: 72px;
  max-height: min(60vh, 440px);
  overflow-y: auto;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 2px 8px #0000001a;
  touch-action: pan-y;
  overscroll-behavior: contain;
}

.level-option {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  height: 44px;
  border: 2px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--ink);
  font:
    500 15px / 1 system-ui,
    sans-serif;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.level-option[aria-selected="true"] {
  border-color: var(--accent);
  background: #0090ff1a;
}

.level-dot {
  position: absolute;
  right: 8px;
  top: 50%;
  width: 6px;
  height: 6px;
  margin-top: -3px;
  border-radius: 50%;
  background: var(--ink);
}

@media (max-width: 720px) {
  .toolbar {
    gap: 4px;
    padding: 6px;
  }
}
import type { StoredObject } from "@stallion/client-store";
import type { StallionBoard } from "@stallion/client-sync";
import { expect, test, vi } from "vitest";
import { type OpenBoard, openSource } from "./sync";

const stored: StoredObject = {
  tile: { level: 0, tx: 0, ty: 0 },
  object: {
    type: "Stroke",
    objectId: "000000000aaaaaaaaaaaa",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
    colour: 0,
    size: "Medium",
    points: [[1, 1, 0.5]],
  },
};

test("a stroke commit goes through put and an erase through remove", () => {
  const put = vi.fn();
  const remove = vi.fn();
  const openBoard: OpenBoard = (url, boardId) => {
    expect([url, boardId]).toEqual(["ws://sync.test", "board"]);
    return { put, remove, status: "Connecting" } as unknown as StallionBoard;
  };
  const connections: string[] = [];
  const source = openSource({
    url: "ws://sync.test",
    boardId: "board",
    openBoard,
    onConnection: (connection) => connections.push(connection),
    onError: (message) => {
      throw new Error(message);
    },
  });

  source.commit(stored);
  source.erase(stored.object.objectId);

  expect(put).toHaveBeenCalledWith(stored);
  expect(remove).toHaveBeenCalledWith(stored.object.objectId);
  expect(connections).toEqual(["Reconnecting"]);
});

