const url = `${SITE}/b/${boardId}`;
const results = [];
const log = (line) => { results.push(line); console.log(line); };

const watch = (name, page) => {
  const events = [];
  page.on("console", (m) => {
    if (m.type() !== "error") return;
    if (/favicon/.test(m.location().url ?? "")) return;
    events.push(`${name} console: ${m.text()}`);
  });
  page.on("pageerror", (e) => events.push(`${name} pageerror: ${e.message}`));
  page.on("response", (r) => { if (r.status() >= 400) events.push(`${name} HTTP ${r.status()} ${r.request().method()} ${r.url()}`); });
  return events;
};

const circle = (cx, cy, r) => Array.from({ length: 91 }, (_, i) => ({ x: cx + Math.cos((i / 90) * Math.PI * 2) * r, y: cy + Math.sin((i / 90) * Math.PI * 2) * r }));
const draw = async (page, points) => {
  const [first, ...rest] = points;
  await page.mouse.move(first.x, first.y);
  await page.mouse.down();
  for (const p of rest) { await page.mouse.move(p.x, p.y); await page.waitForTimeout(10); }
  await page.mouse.up();
};
const ink = (page, colour) => page.evaluate(([r, g, b]) => {
  const c = document.querySelector("canvas.surface");
  const d = c.getContext("2d").getImageData(0, 0, c.width, c.height).data;
  let n = 0;
  for (let i = 0; i < d.length; i += 4) if (d[i + 3] > 200 && Math.abs(d[i] - r) + Math.abs(d[i + 1] - g) + Math.abs(d[i + 2] - b) < 60) n++;
  return n;
}, colour.rgb);
const status = (page) => page.locator(".status[data-connection]").getAttribute("data-connection");
const waitStatus = async (page, want, ms = 15000) => {
  const end = Date.now() + ms;
  while (Date.now() < end) { if ((await status(page)) === want) return true; await page.waitForTimeout(250); }
  return false;
};
const pick = async (page, colour) => {
  await page.getByRole("button", { name: "Large pencil" }).click();
  await page.getByRole("button", { name: colour.label, exact: true }).click();
